package com.chahinaz.pos.operations;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/management/approvals") public class ApprovalController{private final ApprovalService service;public ApprovalController(ApprovalService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ApprovalService.View approve(@Valid @RequestBody ApprovalService.Input in,Authentication a){return service.approve(in,a);}}
